import sys

read = sys.stdin.read

readline = sys.stdin.readline

readlines = sys.stdin.readlines



from math import sqrt



def divisor_enumeration(n):

    div = []

    for i in range(1, int(sqrt(n))+1):

        if n % i == 0:

            if n // i != i:

                div.append((i, n // i))

            else:

                div.append((i, i))



    return div





def main():

    N = int(readline())



    d = divisor_enumeration(N)



    ans = 10**15

    for x, y in d:

        ans = min(ans, x + y - 2)



    print(ans)





if __name__ == "__main__":

    main()

