import sys
def solve(A: int, B: int, C: int, X: int, Y: int):
    c = 0
    if A + B < 2 * C:
        c += min(X, Y) * (A + B)
    else:
        c += min(X, Y) * 2 * C
    if X > Y:
        c += (X - Y) * min(A, 2 * C)
    else:
        c += (Y - X) * min(B, 2 * C)
    print(c)
    return
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    A = int(next(tokens))
    B = int(next(tokens))
    C = int(next(tokens))
    X = int(next(tokens))
    Y = int(next(tokens))
    solve(A, B, C, X, Y)
