p = [ int(x) for x in input().split() ]



seg_tree = SegmentTree(n)

for i in range(n):

    seg_tree.add(i, (1+p[i])/2)



ans = 0

for i in range(n-k+1):

    ans = max(ans, seg_tree.sum(i, i+k))



print(ans)

