INF = float("inf")
MOD = 10**9 + 7


def factorize(num: int) -> dict:
    """ËØÒòÊý·Ö½â"""
    from math import sqrt
    from collections import Counter

    d = Counter()
    # ½Kµã¤Ï¥ë©`¥ÈÇÐ¤êÎ¤Æ+1
    for i in range(2, int(sqrt(num)) + 1):
        # ËØÒòÊý·Ö½â£ºÐ¡¤µ¤¤·½¤«¤é¸î¤ì¤ë¤À¤±¸î¤Ã¤ÆËØÊý¤ò¥«¥¦¥ó¥È
        while num % i == 0:
            num //= i
            d[i] += 1
        # 1¤Þ¤Ç·Ö½â¤·¤¿¤é½KÁË
        if num == 1:
            break
    # ×îáá¤Ë²Ð¤Ã¤¿num¤ÏËØÊý(¤¿¤À¤·1^1¤Ï1^0¤Ê¤Î¤ÇÊý¤ËÈë¤ì¤Ê¤¤)
    if num != 1:
        d[num] += 1
    return d


class FactInvMOD:
    """ëA\¤¿¤¯¤µ¤óÊ¹¤¦rÓÃ¤Î¥Æ©`¥Ö¥ëÊä"""

    def __init__(self, MAX, MOD):
        """MAX£ºëA\¤ËÊ¹¤¦Êý¤Î×î´óÒÔÉÏ¤Þ¤Ç×÷¤ë"""
        MAX += 1
        self.MAX = MAX
        self.MOD = MOD
        # ëA\¥Æ©`¥Ö¥ë
        factorial = [1] * MAX
        factorial[0] = factorial[1] = 1
        for i in range(2, MAX):
            factorial[i] = factorial[i - 1] * i % MOD
        # ëA\¤ÎÄæÔª¥Æ©`¥Ö¥ë
        inverse = [1] * MAX
        # pow¤ËµÚÈýÒýÊýÈë¤ì¤ë¤Èç\¤Îmod¸¶ÓËã¤ò¸ßËÙ¤Ë¤ä¤Ã¤Æ¤¯¤ì¤ë
        inverse[MAX - 1] = pow(factorial[MAX - 1], MOD - 2, MOD)
        for i in range(MAX - 2, 0, -1):
            # ×îáá¤«¤éø¤Ã¤Æ¤¤¤¯¤³¤Î¥ë©`¥×¤Ê¤éMAX»Øpow¤¹¤ë¤è¤êIÀí¤¬ËÙ¤¤
            inverse[i] = inverse[i + 1] * (i + 1) % MOD
        self.fact = factorial
        self.inv = inverse

    def nCr(self, n, r):
        """½M¤ßºÏ¤ï¤»¤ÎÊý (±ØÒª¤ÊëA\¤ÈÄæÔª¤Î¥Æ©`¥Ö¥ë¤òÊÂÇ°¤Ë×÷¤Ã¤Æ¤ª¤¯)"""
        if n < r:
            return 0
        # 10C7 = 10C3
        r = min(r, n - r)
        # ·Ö×Ó¤ÎÓËã
        numerator = self.fact[n]
        # ·ÖÄ¸¤ÎÓËã
        denominator = self.inv[r] * self.inv[n - r] % self.MOD
        return numerator * denominator % self.MOD

    def nPr(self, n, r):
        """íÁÐ"""
        if n < r:
            return 0
        return self.fact[n] * self.inv[n - r] % self.MOD

    def nHr(self, n, r):
        """ÖØÑ}½M¤ßºÏ¤ï¤»"""
        # rßx¤Ö¤È¤³¤í¤ËN-1¤ÎÊËÇÐ¤ê¤òÈë¤ì¤ë
        return self.nCr(r + n - 1, r)


N, M = MAP()
