import sys
def main():
    s = input().rstrip()
    permitted = 'ACGT'
    continuous_count = []
    count = 0
    for i in range(len(s)):
        char = s[i]
        if char in permitted:
            count += 1
        else:
            continuous_count.append(count)
            count = 0
        if i == len(s) - 1:
            continuous_count.append(count)
    if not continuous_count:
        print(len(s))
    else:
        print(max(continuous_count))
