def exit(*argv, **kwarg):
    print(*argv, **kwarg)
    sys.exit()


def mina(*argv, sub=1):
    return list(map(lambda x: x - sub, argv))


# ÊÜ¤±¶É¤µ¤ì¤¿¤¹¤Ù¤Æ¤ÎÒªËØ¤«¤ésub¤À¤±Òý¤¯.¥ê¥¹¥È¤ò*¤ò¤Ä¤±¤ÆÕ¹é_¤·¤Æ¤ª¤¯¤³¤È
def a_int():
    return int(readline())


def ints():
    return list(map(int, readline().split()))


from collections import Counter


class FastFactorization:
    def __init__(self, N: int):
        """ºBO(NloglogN)¡¢¥¯¥¨¥êO(logN)"""
        self.N = N
        self.min_prime = self._make_minimum_prime()

    def _make_minimum_prime(self):
        # x¤Î×îÐ¡¤ÎËØÒòÊý±í¤ò×÷³É
        min_prime = [x for x in range(self.N + 1)]
        # min_prime[0] = 0  # 0¤È1¤ÏËØÊý¤Ç¤Ï¤Ê¤¤
        # min_prime[1] = 1
        for i in range(2, int(self.N**0.5) + 1):
            if min_prime[i] == i:  # ËØÊý¤À¤Ã¤¿¤é¸üÐÂ
                for j in range(2 * i, self.N + 1, i):  # i¤Î±¶Êý¤ÏËØÊý¤Ç¤Ê¤¤
                    if min_prime[j] == j:
                        min_prime[j] = i
        return min_prime

    def query(self, x: int):
        # -> Counter[p,n] (ËØÊý,çÊý) ¤ò¸ñ¼{
        # ×îÐ¡ËØÊýÅäÁÐmin_prime¤òÊ¹¤Ã¤ÆO(log N)¤ÇÒòÊý·Ö½â
        if x == 1:
            return Counter()  # 1¤ÏËØÊý¤Ç¤Ï¤Ê¤¤
        # ËØÒòÊý·Ö½â
        arr = []
        tmp = x
        while tmp != 1:
            p = self.min_prime[tmp]
            tmp //= p
            arr.append(p)
        return Counter(arr)


