    solve(a, b, c, x, y, z, k)
def solve(a, b, c, x, y, z, k):
    a.sort(reverse=True)
    b.sort(reverse=True)
    c.sort(reverse=True)
    stack = list()
    for p in range(x):
        for q in range(y):
            if (p + 1) * (q + 1) > k:
                break
            for r in range(z):
                if (p + 1) * (q + 1) * (r + 1) > k:
                    break
                stack.append(a[p] + b[q] + c[r])
    stack.sort(reverse=True)
    for i in range(k):
        print(stack[i])
