import sys

import itertools

import collections





def solve():

    readline = sys.stdin.buffer.readline

    mod = 10 ** 9 + 7

    n = int(readline())

    xy = []

    for i in range(n):

        a = int(readline())

        for j in range(a):

            x, y = list(map(int, readline().split()))

            xy.append([i, x-1, y])

    ls = collections.deque([v for v in itertools.product([True, False], repeat=n)])

    for i, x, y in xy:

        for j in range(len(ls)):

            lsv = ls.pop()

            if not lsv[i] or lsv[x] == bool(y):

                ls.appendleft(lsv)

    t = 0

    for i in range(len(ls)):

        t = max(t, ls[i].count(True))

    print(t)





if __name__ == '__main__':

    solve()

