from collections import defaultdict





def main():

    N = int(eval(input()))

    heights = list(map(int, input().split()))



    """

    for j>i, j-i = Ai + Aj

    i + Ai = j -Aj

    """



    L = defaultdict(int)

    R = defaultdict(int)



    for i, height in enumerate(heights):

        if i + height < N:

            L[i + height] += 1



        if i - height > 0:

