#!/usr/bin/env python3

class UnionFind():

    def __init__(self, n):

        self.n = n

        self.parents = [-1] * n



    def find(self, x):

        if self.parents[x] < 0:

            return x

        else:

            self.parents[x] = self.find(self.parents[x])

            return self.parents[x]



    def union(self, x, y):

        x = self.find(x)

        y = self.find(y)



        if x == y:

            return



        if self.parents[x] > self.parents[y]:

            x, y = y, x



        self.parents[x] += self.parents[y]

        self.parents[y] = x





    def same(self, x, y):

        return self.find(x) == self.find(y)



import numpy as np

N, M = list(map(int, input().split()))

edge = []

for _ in range(M):

    edge.append(list(map(int, input().split())))

ans = 0 

for i in range(M):

    unionfind = UnionFind(N)

    for j in [k for k in range(M) if k != i]:

        a, b = edge[j][0] - 1, edge[j][1] - 1

        unionfind.union(a, b)

    if np.count_nonzero(np.array(unionfind.parents) < 0) >= 2:

        ans += 1

print(ans)

