for start in range(1,n+1):

    targets=relations.get(start,[])

    color=1

    for target in targets:

        if color == nodes[start]:

            color+=1

        else:

            pass

        nodes[target]=color

        if color>=max_color:

            max_color=color

        color+=1



print(max_color)

